<?php require 'db.php';require 'helpers.php';require_admin();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="students.csv"');$o=fopen('php://output','w');fputcsv($o,['Enrollment','Name','Email','Mobile','Course','Status']);foreach($pdo->query("SELECT enrollment_number,name,email,mobile,course,status FROM students WHERE status='active'") as $r)fputcsv($o,$r);fclose($o);audit($pdo,'student_export','CSV exported');exit;?>